              </template>
              <p style="font-size: 12px; line-height: 1.65; color: var(--color-steel); margin: 14px 0 0;"><span v-if="__s(v.d?.disclosure) !== null" class="sc-interp">{{ __s(v.d?.disclosure) }}</span></p>
            </div>
          </div>
        </template>

