          <div style="display: flex; background: var(--color-off-white); border-radius: 999px; padding: 3px;">
            <template v-for="(t, $index) in __arr(v.mob?.toggle)" :key="$index">
              <button @click="t?.go" :style="t?.style"><span v-if="__s(t?.label) !== null" class="sc-interp">{{ __s(t?.label) }}</span></button>
            </template>
          </div>
          <button @click="v.mob?.back" :style="v.mob?.backStyle"><span v-if="__s(v.mob?.backLabel) !== null" class="sc-interp">{{ __s(v.mob?.backLabel) }}</span></button>
        </div>
